settings.custom_liquid:
{%- comment -%}
  Minimal Collection Breadcrumb (i18n)
  Output: [Localized parent] / {{ collection.title }}
  - No Home
  - Locale-aware parent title + URL (no redirects)
  - Max width: 1200px
  - Desktop: no left padding
  - Mobile: extra padding
  - Color: #BF1E2D
  - Font size: 16px
  - JSON-LD included
{%- endcomment -%}

{%- assign locale = request.locale.iso_code | downcase -%}
{%- assign parent_title = 'Rubber fenders' -%}
{%- assign parent_url = '/collections/rubber-fenders' -%}

{%- case locale -%}
  {%- when 'de' -%}
    {%- assign parent_title = 'Gummi-Fender' -%}
    {%- assign parent_url = '/collections/gummifender' -%}

  {%- when 'es' -%}
    {%- assign parent_title = 'Defensas de goma' -%}
    {%- assign parent_url = '/collections/defensas-de-goma' -%}

  {%- when 'fr' -%}
    {%- assign parent_title = 'Défenses en caoutchouc' -%}
    {%- assign parent_url = '/collections/defenses-en-caoutchouc' -%}

  {%- when 'it' -%}
    {%- assign parent_title = 'Parabordi in gomma' -%}
    {%- assign parent_url = '/collections/parabordi-in-gomma' -%}

  {%- when 'sv-se' -%}
    {%- assign parent_title = 'Gummifendrar' -%}
    {%- assign parent_url = '/collections/gummi-fender' -%}

  {%- when 'da-dk' -%}
    {%- assign parent_title = 'Gummifendere' -%}
    {%- assign parent_url = '/collections/rubber-fenders' -%}

  {%- when 'no' -%}
    {%- assign parent_title = 'Gummifendere' -%}
    {%- assign parent_url = '/collections/rubber-fenders' -%}

  {%- when 'nl' -%}
    {%- assign parent_title = 'Rubber fenders' -%}
    {%- assign parent_url = '/collections/rubber-fenders' -%}
{%- endcase -%}

<div class="breadcrumbs-wrap">
  <nav class="breadcrumbs" aria-label="Breadcrumb">
    <ol class="breadcrumbs__list" role="list">
      <li class="breadcrumbs__item">
        <a class="breadcrumbs__link" href="{{ parent_url }}">
          {{ parent_title }}
        </a>
      </li>

      <li class="breadcrumbs__item" aria-hidden="true">/</li>

      <li class="breadcrumbs__item">
        <span class="breadcrumbs__current" aria-current="page">
          {{ collection.title }}
        </span>
      </li>
    </ol>
  </nav>
</div>

<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "BreadcrumbList",
  "itemListElement": [
    {
      "@type": "ListItem",
      "position": 1,
      "name": {{ parent_title | json }},
      "item": "{{ shop.url }}{{ parent_url }}"
    },
    {
      "@type": "ListItem",
      "position": 2,
      "name": {{ collection.title | json }},
      "item": "{{ shop.url }}{{ collection.url }}"
    }
  ]
}
</script>

<style>
  .breadcrumbs-wrap {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0; /* desktop: strak links */
  }

  /* Mobile: extra ruimte links/rechts (Dawn-like, iets ruimer) */
  @media screen and (max-width: 749px) {
    .breadcrumbs-wrap {
      padding-left: 2rem;
      padding-right: 2rem;
    }
  }

  .breadcrumbs {
    margin: 0;
    padding: 0;
    font-size: 16px;
    line-height: 1.2;
    color: #BF1E2D;
  }

  .breadcrumbs__list {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0;
    margin: 0;
    list-style: none;
    flex-wrap: wrap;
  }

  .breadcrumbs__link {
    color: #BF1E2D;
    text-decoration: none;
  }

  .breadcrumbs__link:hover {
    text-decoration: underline;
  }

  .breadcrumbs__current {
    color: #BF1E2D;
    opacity: 0.9;
  }
</style>

{%- assign locale = request.locale.iso_code | downcase -%}

{%- if locale == 'en' or locale contains 'en-' -%}

{%- liquid
  assign mf_html_obj = collection.metafields.custom.text_schuinestreep

  assign mf_html = mf_html_obj.value | default: mf_html_obj | default: ''
  assign mf_html = mf_html | strip

  assign default_html = '<h3>High quality ' | append: collection.title | append: '</h3><ul><li><strong>Wide range</strong> of rubber fenders &amp; bumpers</li><li><strong>Cut &amp; pre-drilled</strong> fenders with fast lead times</li><li><strong>Bespoke designs</strong> for special fenders and bumpers</li><li><strong>Short production times</strong> and reliable delivery</li><li><strong>60+ years</strong> of manufacturing experience</li></ul>'

  assign content_html = default_html
  if mf_html != blank
    assign content_html = mf_html
  endif

  comment
    Image behavior:
    - Desktop SVG uses img_url (collection image by default; no metafield image used in this version)
    - Mobile: shows ONLY a plain <img> (no stripes/band/diagonal), fully visible (contain), not zoomed/cropped.
  endcomment

  assign fallback_img_url = 'https://cdn.shopify.com/s/files/1/0679/5221/4281/files/RuplaTec_wearhouse_0209f064-9115-4d1a-bc92-091180234a31.jpg?v=1768464934'

  assign img_url = fallback_img_url
  if collection.image != blank
    assign img_url = collection.image | image_url: width: 2000
  endif

  assign uid = section.id | append: '-' | append: collection.id
  assign uid = uid | replace: '-', '' | replace: '_', '' | replace: ' ', ''

  assign bannerH     = 280
  assign diagTopX    = 177
  assign diagBottomX = 350
  assign foldW       = 26
  assign bandW       = 34
  assign bandTopY    = 84

  assign leftPadX  = 96
  assign rightPadX = 52

  assign delta = diagBottomX | minus: diagTopX
  assign diagAtBandY = delta | times: bandTopY | divided_by: bannerH | plus: diagTopX
-%}

<style>
.rt-{{ uid }}{
  --bandColor:#BF1E2D;
}

.rt-{{ uid }}.rt-wrap{
  max-width:1200px;
  margin:0 auto;
  border:1px solid #d9d9d9;
  background:#fff;
  overflow:hidden;
}

.rt-{{ uid }} .rt-banner{
  display:flex;
  height:{{ bannerH }}px;
}

.rt-{{ uid }} .rt-left{
  width:60%;
  padding:14px {{ rightPadX }}px 14px {{ leftPadX }}px;
  box-sizing:border-box;
  display:flex;
  align-items:center;
}

.rt-{{ uid }} .rt-left .c{
  max-width:680px;
  width:100%;
}

.rt-{{ uid }} .rt-left h3{
  margin:0 0 18px;
  font-size:24px;
  font-weight:600;
}

.rt-{{ uid }} .rt-left ul{
  margin:0;
  padding-left:18px;
}

.rt-{{ uid }} .rt-left li{
  margin:8px 0;
  font-size:16px;
  line-height:1.45;
}

.rt-{{ uid }} .rt-right{
  width:47%;
  position:relative;
  background:#fff;
  overflow:hidden;
}

.rt-{{ uid }} .rt-right svg{
  display:block;
  width:700px;
  height:{{ bannerH }}px;
  max-width:none;
}

.rt-{{ uid }} .rt-svg-desktop{
  position:absolute;
  top:0;
  right:0;
}

.rt-{{ uid }} .rt-img-mobile{
  display:none;
}

@media (max-width:900px){

  .rt-{{ uid }}.rt-wrap{
    border:none;
    background:transparent;
    padding:0 16px;
    overflow:visible;
  }

  .rt-{{ uid }} .rt-banner{
    flex-direction:column;
    height:auto;
    gap:12px;
  }

  .rt-{{ uid }} .rt-right{
    width:100%;
    order:1;
    overflow:visible;
    height:auto;
    background:#fff;
  }

  .rt-{{ uid }} .rt-svg-desktop,
  .rt-{{ uid }} .rt-svg-mobile{
    display:none !important;
  }

  .rt-{{ uid }} .rt-img-mobile{
    display:block !important;
    width:100%;
    height:auto;
    object-fit:contain;
    background:#fff;
  }

  .rt-{{ uid }} .rt-left{
    width:100%;
    padding:0;
    order:2;
    align-items:flex-start;
  }

  .rt-{{ uid }} .rt-left .c{
    background:#fff;
    padding:16px 16px 18px;
  }
}
</style>

<div class="rt-wrap rt-{{ uid }}">
  <div class="rt-banner">
    <div class="rt-left">
      <div class="c">
        {{ content_html }}
      </div>
    </div>

    <div class="rt-right">
      <svg class="rt-svg-desktop" viewBox="0 0 700 {{ bannerH }}" preserveAspectRatio="xMidYMid meet" aria-hidden="true"
           xmlns="http://www.w3.org/2000/svg"
           xmlns:xlink="http://www.w3.org/1999/xlink">
        <defs>
          <clipPath id="imgClip-{{ uid }}">
            <polygon points="{{ diagTopX }},0 700,0 700,{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"></polygon>
          </clipPath>

          <clipPath id="shadowOnPhotoSide-{{ uid }}">
            <polygon points="{{ diagTopX }},0 700,0 700,{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"></polygon>
          </clipPath>

          <filter id="sh_fold_soft-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="24" dy="1" stdDeviation="16" flood-color="#000" flood-opacity="0.14"/>
          </filter>

          <filter id="sh_fold_contact-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="10" dy="5" stdDeviation="4.2" flood-color="#000" flood-opacity="0.045"/>
          </filter>

          <filter id="sh_band_only-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow in="SourceAlpha" dx="27" dy="17" stdDeviation="4.8" flood-color="#000" flood-opacity="0.22" result="ds1"/>
            <feDropShadow in="SourceAlpha" dx="52" dy="30" stdDeviation="26" flood-color="#000" flood-opacity="0.12" result="ds2"/>
            <feMerge>
              <feMergeNode in="ds1"/>
              <feMergeNode in="ds2"/>
            </feMerge>
          </filter>

          <linearGradient id="bandShine-{{ uid }}" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#ffffff" stop-opacity="0.00"/>
            <stop offset="25%" stop-color="#ffffff" stop-opacity="0.22"/>
            <stop offset="50%" stop-color="#ffffff" stop-opacity="0.06"/>
            <stop offset="75%" stop-color="#ffffff" stop-opacity="0.18"/>
            <stop offset="100%" stop-color="#ffffff" stop-opacity="0.00"/>
          </linearGradient>

          <clipPath id="bandClip-{{ uid }}">
            <polygon points="{{ diagAtBandY }},{{ bandTopY }} {{ diagAtBandY | plus: bandW }},{{ bandTopY }} {{ diagBottomX | plus: bandW }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"></polygon>
          </clipPath>
        </defs>

        <g clip-path="url(#imgClip-{{ uid }})">
          <rect x="0" y="0" width="700" height="{{ bannerH }}" fill="#fff"/>
          <image xlink:href="{{ img_url }}" href="{{ img_url }}"
                 x="0" y="0" width="700" height="{{ bannerH }}"
                 preserveAspectRatio="xMaxYMid meet" />
        </g>

        <polygon
          points="{{ diagAtBandY }},{{ bandTopY }} {{ diagAtBandY | plus: bandW }},{{ bandTopY }} {{ diagBottomX | plus: bandW }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"
          fill="#000" filter="url(#sh_band_only-{{ uid }})"/>

        <polygon
          points="{{ diagAtBandY }},{{ bandTopY }} {{ diagAtBandY | plus: bandW }},{{ bandTopY }} {{ diagBottomX | plus: bandW }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"
          fill="var(--bandColor)"/>

        <g clip-path="url(#bandClip-{{ uid }})" opacity="0.9">
          <rect x="0" y="0" width="700" height="{{ bannerH }}" fill="url(#bandShine-{{ uid }})"/>
        </g>

        <g clip-path="url(#shadowOnPhotoSide-{{ uid }})">
          <g filter="url(#sh_fold_soft-{{ uid }})">
            <polygon points="{{ diagTopX | minus: foldW }},0 {{ diagTopX }},0 {{ diagBottomX }},{{ bannerH }} {{ diagBottomX | minus: foldW }},{{ bannerH }}" fill="#fff"/>
          </g>
          <g filter="url(#sh_fold_contact-{{ uid }})">
            <polygon points="{{ diagTopX | minus: foldW }},0 {{ diagTopX }},0 {{ diagBottomX }},{{ bannerH }} {{ diagBottomX | minus: foldW }},{{ bannerH }}" fill="#fff"/>
          </g>
        </g>

        <polygon points="{{ diagTopX | minus: foldW }},0 {{ diagTopX }},0 {{ diagBottomX }},{{ bannerH }} {{ diagBottomX | minus: foldW }},{{ bannerH }}" fill="#fff"/>
        <polygon points="{{ diagTopX }},0 {{ diagTopX | plus: 2 }},0 {{ diagBottomX | plus: 2 }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}" fill="#000" opacity="0.06"/>
      </svg>

      <img
        class="rt-img-mobile"
        src="{{ img_url }}"
        alt="{{ collection.title | escape }}"
        loading="lazy"
        width="700"
        height="{{ bannerH }}"
      >
    </div>
  </div>
</div>

{%- endif -%}
